export default function RichTooltip({
  trigger,
  title,
  description,
  icon,
  href,
  actionLabel,
  actionHref,
  onActionClick,
  meta,
  className = "",
  side = "top",
  align = "center",
}: RichTooltipProps) {
  const shouldReduceMotion = useReducedMotion();
  const Title = (
    <div className="flex items-center gap-2 font-medium text-sm">
      {icon ?? <YouTubeIcon />}
      {href ? (
        <a
          className="inline-flex items-center gap-1 hover:underline"
          href={href}
          rel="noopener noreferrer"
          target="_blank"
        >
          <span>{title}</span>
          <ExternalLink className="h-3.5 w-3.5 opacity-70" />
        </a>
      ) : (
        <span>{title}</span>
      )}
    </div>
  );

  const renderAction = () => {
    if (!actionLabel) {
      return null;
    }

    const actionClassName =
      "bg-white text-black hover:bg-white/90 dark:bg-white dark:text-black";

    if (actionHref) {
      return (
        <SmoothButton
          asChild
          className={actionClassName}
          shape="pill"
          size="xs"
          variant="solid"
        >
          <a href={actionHref} rel="noopener noreferrer" target="_blank">
            <Play className="h-3.5 w-3.5" /> {actionLabel}
          </a>
        </SmoothButton>
      );
    }

    return (
      <SmoothButton
        className={actionClassName}
        onClick={onActionClick}
        shape="pill"
        size="xs"
        type="button"
        variant="solid"
      >
        <Play className="h-3.5 w-3.5" /> {actionLabel}
      </SmoothButton>
    );
  };

  const Action = renderAction();

  return (
    <PopoverRoot>
      <PopoverTrigger asChild>{trigger}</PopoverTrigger>
      <PopoverPortal>
        <PopoverContent
          align={align}
          asChild
          className={cn("z-50", className)}
          side={side}
          sideOffset={8}
        >
          <motion.div
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(0px)", opacity: 1, scale: 1, y: 0 }
            }
            className="relative rounded-2xl border border-white/10 bg-black px-4 py-3 text-white shadow-xl"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { filter: "blur(8px)", opacity: 0, scale: 0.95, y: 5 }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(8px)", opacity: 0, scale: 0.95, y: 5 }
            }
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : {
                    damping: 30,
                    duration: 0.2,
                    stiffness: 500,
                    type: "spring" as const,
                  }
            }
          >
            {Title}
            {description ? (
              <p className="mt-3 max-w-xs text-balance text-base text-white/90 leading-relaxed">
                {description}
              </p>
            ) : null}
            {meta || Action ? (
              <div className="mt-4 flex items-center justify-between gap-3">
                {meta ? (
                  <span className="inline-flex items-center gap-1 rounded-full bg-white/10 px-3 py-1 text-white text-xs">
                    <Clock className="h-3.5 w-3.5" /> {meta}
                  </span>
                ) : (
                  <span />
                )}
                {Action}
              </div>
            ) : null}

            {/* Tail */}
            <PopoverArrow className="fill-black" />
          </motion.div>
        </PopoverContent>
      </PopoverPortal>
    </PopoverRoot>
  );
}

